/**
 * Data access for server components and generateStaticParams.
 * Everything is read from the compiled JSON in src/data (regenerated by scripts/build-data.mjs
 * before every dev/build). Client components should receive data as props, not import this,
 * to keep the client bundle small — except `IssueLite` lists, which are deliberately compact.
 */
import issuesJson from '@/data/issues.json';
import lifespansJson from '@/data/lifespans.json';
import metaJson from '@/data/meta.json';
import type { DataMeta, Issue, Lifespan } from './types';
import { issuesForYear } from './select';
import { MAX_YEAR, MIN_YEAR } from './site';

const ISSUES = issuesJson as Issue[];
const LIFESPANS = lifespansJson as Lifespan[];
const BY_SLUG = new Map(ISSUES.map((i) => [i.slug, i]));

export const getIssues = (): Issue[] => ISSUES;
export const getIssue = (slug: string): Issue | undefined => BY_SLUG.get(slug);
export const getLifespans = (): Lifespan[] => LIFESPANS;
export const getMeta = (): DataMeta => metaJson as DataMeta;

/** All issues that apply to `year`, sorted (priority, core, severity). Optional state filter. */
export const getIssuesForYear = (year: number, state?: string | null): Issue[] => issuesForYear(ISSUES, year, state);

/** Every build year we generate a report for, MIN_YEAR..MAX_YEAR. */
export const allYears = (): number[] => Array.from({ length: MAX_YEAR - MIN_YEAR + 1 }, (_, i) => MIN_YEAR + i);

/**
 * The subset of Issue fields needed to draw timelines and previews on the client.
 * Pass this (not full issues) to client components to keep payloads small.
 */
export type IssueLite = Pick<
  Issue,
  'id' | 'slug' | 'title' | 'category' | 'hook' | 'kind' | 'applies' | 'regions' | 'severity' | 'priority' | 'evidence' | 'prevalence'
>;
export const toLite = (i: Issue): IssueLite => ({
  id: i.id, slug: i.slug, title: i.title, category: i.category, hook: i.hook, kind: i.kind,
  applies: i.applies, regions: i.regions, severity: i.severity, priority: i.priority,
  evidence: i.evidence, prevalence: i.prevalence,
});
export const getIssuesLite = (): IssueLite[] => ISSUES.map(toLite);
